from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
def read(p): return (ROOT/p).read_text()
def load(p): return json.loads(read(p))
def test_m276_release_and_contract():
 d=load('data/release_identity.json'); assert d['milestone'] in {'M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'} and d['client_version'] in {'0.276.0','0.277.0','0.278.0','0.279.0','0.280.0','0.281.0','0.282.0','0.283.0','0.284.0','0.285.0','0.286.0','0.287.0','0.288.0','0.289.0','0.290.0','0.291.0','0.292.0','0.293.0','0.294.0','0.295.0','0.296.0','0.297.0','0.298.0','0.299.0','0.300.0','0.301.0'} and d['build_number'] in {276,277,278,279,280,281,282,283,284,285,286,287,288,289,290,291,292,293,294,295,296,297,298,299,300,301} and d['content_config_version'] in {'M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'} and d['master_concept']=='V3.8'
 c=load('data/m276_authoritative_loot_roll_integrity_contract.json'); assert c['contract']=='authoritative_loot_roll_ledger_rng_integrity_duplicate_protection_guaranteed_pity_foundation'; assert c['genre_ux_references']==['Seafight','Battle of Sea']; assert all(x in c['authority']['server_owns'] for x in ['roll_id','idempotency_key','rng_resolution','duplicate_guard','result_digest','guaranteed_state','pity_state'])
def test_m276_runtime_fail_closed_revision_and_replay_guarded():
 s=read('scripts/online/m276_authoritative_loot_roll_integrity_runtime.gd')
 for t in ['bind_loot_distribution','ingest_server_roll_snapshot','ingest_server_roll_event','roll_ledger_revision','pity_revision','roll_ledger','duplicate_guard_state','guaranteed_state','pity_state','rng_integrity_state','REQUIRED_ROLL_IDENTITY','invalidate_from_world_resync']: assert t in s
 for t in ['can_client_generate_roll_id() -> bool: return false','can_client_choose_rng_seed() -> bool: return false','can_client_roll_drop() -> bool: return false','can_client_reroll_drop() -> bool: return false','can_client_bypass_duplicate_guard() -> bool: return false','can_client_advance_pity() -> bool: return false','can_client_trigger_guaranteed_drop() -> bool: return false','can_client_override_result_digest() -> bool: return false','can_client_authorize_settlement() -> bool: return false','can_client_transfer_test_roll_to_global() -> bool: return false']: assert t in s
 assert 'rr <= roll_ledger_revision' in s and 'raw_seed' in s and 'secret_entropy' in s and '"can_reroll":false' in s
def test_m276_bootstrap_deck_admin_dependencies():
 b=read('scripts/core/game_bootstrap.gd'); deck=read('scripts/ui/command_deck.gd'); assert 'M276AuthoritativeLootRollIntegrityRuntime.new()' in b and 'AuthoritativeLootRollIntegrityReadiness' in b; assert 'LOOT ROLL LEDGER · RNG · DUPLICATE · PITY' in deck and 'M276AuthoritativeLootRollIntegrityCatalog.pity()' in deck
 a=load('data/admin_content_type_registry.json'); assert a['milestone'] in {'M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'} and all(x in a['content_types'] for x in ['loot_roll_integrity_policy_definition','loot_duplicate_guard_policy_definition','guaranteed_drop_policy_definition','loot_pity_policy_definition'])
 c=load('data/m276_authoritative_loot_roll_integrity_contract.json'); assert c['dependencies']['distribution'].startswith('M275') and c['dependencies']['eligibility'].startswith('M274') and c['dependencies']['encounter'].startswith('M273') and c['dependencies']['settlement'].startswith('M266')
def test_m276_convergence_and_unset_tuning():
 m=load('data/m239_master_convergence_matrix.json'); assert m['milestone'] in {'M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'}; row={x['domain']:x for x in m['domains']}['authoritative_loot_roll_ledger_rng_integrity_duplicate_protection_guaranteed_pity']; assert row['status']=='PARTIAL' and 'm276_fix' in row and any(x.startswith('production authoritative loot-roll ledger') for x in row['remaining'])
 c=load('data/m276_authoritative_loot_roll_integrity_contract.json'); assert all(x in c['unset_until_measured'] for x in ['rng_algorithm','drop_probabilities','guaranteed_drop_thresholds','pity_thresholds','pity_reset_rules','reward_values'])
